def gen(rng):
    tests = ['0', '3', '1', '2', '8', '100', '1234', '00', '03', '000', '30', '10', '20', '11', '12', '0000001', '2020', '1001', '99999']
    for n in (2, 3, 4, 5, 6, 8, 10, 12):
        for _ in range(4):
            mode = rng.randrange(3)
            if mode == 0:
                tests.append(''.join(rng.choice('0123456789') for _ in range(n)))
            elif mode == 1:
                tests.append(''.join(rng.choice('012') for _ in range(n)))
            else:
                tests.append(''.join(rng.choice('00124578') for _ in range(n)))
    n = 100000
    tests.append(''.join(rng.choice('0123456789') for _ in range(n)))
    tests.append('0' * n)
    tests.append('1' * n)
    tests.append('0' * (n // 2) + '1' * (n // 2 - 1) + '2')
    tests.append('2' * (n - 1) + '1')
    tests.append('0' + ''.join(rng.choice('1245780') for _ in range(n - 1)))
    return tests
